$$ LANGUAGE sql STABLE;

-- calc_graphs_count_of_stated_facts
-- Field: Graphs.CountOfStatedFacts
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_graphs_count_of_stated_facts(p_graph_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((calc_statements_in_effect_unit(statement_id))::numeric), 0) FROM statements WHERE graph = p_graph_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_graphs_count_of_conclusions
-- Field: Graphs.CountOfConclusions
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_graphs_count_of_conclusions(p_graph_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((calc_statements_conclusion_unit(statement_id))::numeric), 0) FROM statements WHERE graph = p_graph_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_graphs_count_of_violations
-- Field: Graphs.CountOfViolations
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_graphs_count_of_violations(p_graph_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((calc_disjoint_checks_violation_unit(disjoint_check_id))::numeric), 0) FROM disjoint_checks WHERE graph = p_graph_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_graphs_is_consistent
-- Field: Graphs.IsConsistent
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_graphs_is_consistent(p_graph_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_graphs_count_of_violations(p_graph_id))::NUMERIC, 0) = 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_graphs_conclusions_message
-- Field: Graphs.ConclusionsMessage
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_graphs_conclusions_message(p_graph_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((calc_graphs_count_of_conclusions(p_graph_id))::NUMERIC, 0) = 0 THEN ((SELECT NULLIF(no_conclusions_text, '') FROM graphs WHERE graph_id = p_graph_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_graphs_count_of_facts_to_add
-- Field: Graphs.CountOfFactsToAdd
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_graphs_count_of_facts_to_add(p_graph_id TEXT)
