-- calc_graphs_has_facts_to_add
-- Field: Graphs.HasFactsToAdd
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_graphs_has_facts_to_add(p_graph_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (COALESCE((calc_graphs_count_of_facts_to_add(p_graph_id))::NUMERIC, 0) > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_graphs_next_fact_sort_order
-- Field: Graphs.NextFactSortOrder
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_graphs_next_fact_sort_order(p_graph_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(MIN((sort_order)::numeric), 0) FROM statements WHERE graph = p_graph_id AND calc_statements_listed_off_unit(statement_id) = 1))::integer;
$$ LANGUAGE sql STABLE;

-- calc_graphs_max_activation_seq
-- Field: Graphs.MaxActivationSeq
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_graphs_max_activation_seq(p_graph_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(MAX((activation_seq)::numeric), 0) FROM statements WHERE graph = p_graph_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_graphs_next_activation_seq
-- Field: Graphs.NextActivationSeq
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_graphs_next_activation_seq(p_graph_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_graphs_max_activation_seq(p_graph_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_graphs_max_listed_sort_order
-- Field: Graphs.MaxListedSortOrder
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_graphs_max_listed_sort_order(p_graph_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(MAX((sort_order)::numeric), 0) FROM statements WHERE graph = p_graph_id AND calc_statements_listed_unit(statement_id) = 1))::integer;
$$ LANGUAGE sql STABLE;

-- calc_graphs_next_listed_sort_order
-- Field: Graphs.NextListedSortOrder
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_graphs_next_listed_sort_order(p_graph_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_graphs_max_listed_sort_order(p_graph_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::integer;
$$ LANGUAGE sql STABLE;

