-- calc_statements_listed_off_unit
-- Field: Statements.ListedOffUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_listed_off_unit(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(COALESCE((SELECT is_listed FROM statements WHERE statement_id = p_statement_id), FALSE), FALSE) AND COALESCE(NOT (COALESCE(calc_statements_is_in_effect(p_statement_id), FALSE)), FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_is_next_to_add
-- Field: Statements.IsNextToAdd
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_statements_is_next_to_add(p_statement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_statements_listed_off_unit(p_statement_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((SELECT sort_order FROM statements WHERE statement_id = p_statement_id), 0) = COALESCE(calc_statements_next_fact_sort_order(p_statement_id), 0), FALSE)));
$$ LANGUAGE sql STABLE;

