-- calc_firings_inverse_fired_unit
-- Field: Firings.InverseFiredUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_firings_inverse_fired_unit(p_firing_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(calc_firings_rule_enabled(p_firing_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(kind, '') FROM firings WHERE firing_id = p_firing_id), '') = 'inverse', FALSE) AND COALESCE(calc_firings_first_is_in_effect(p_firing_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_firings_symmetric_fired_unit
-- Field: Firings.SymmetricFiredUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_firings_symmetric_fired_unit(p_firing_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(calc_firings_rule_enabled(p_firing_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(kind, '') FROM firings WHERE firing_id = p_firing_id), '') = 'symmetric', FALSE) AND COALESCE(calc_firings_first_is_in_effect(p_firing_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_firings_chain_fired_unit
-- Field: Firings.ChainFiredUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_firings_chain_fired_unit(p_firing_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(calc_firings_rule_enabled(p_firing_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(kind, '') FROM firings WHERE firing_id = p_firing_id), '') = 'chain', FALSE) AND COALESCE(calc_firings_first_holds_before_chain(p_firing_id), FALSE) AND COALESCE(calc_firings_second_holds_before_chain(p_firing_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_firings_type_fired_unit
-- Field: Firings.TypeFiredUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_firings_type_fired_unit(p_firing_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(calc_firings_rule_enabled(p_firing_id), FALSE) AND COALESCE((COALESCE(COALESCE((SELECT NULLIF(kind, '') FROM firings WHERE firing_id = p_firing_id), '') = 'domain', FALSE) OR COALESCE(COALESCE((SELECT NULLIF(kind, '') FROM firings WHERE firing_id = p_firing_id), '') = 'range', FALSE)), FALSE) AND COALESCE(calc_firings_first_holds_before_typing(p_firing_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_firings_fired_unit
-- Field: Firings.FiredUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_firings_fired_unit(p_firing_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_inverse_fired_unit(p_firing_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_symmetric_fired_unit(p_firing_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_chain_fired_unit(p_firing_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_type_fired_unit(p_firing_id)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_firings_order_key
-- Field: Firings.OrderKey
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_firings_order_key(p_firing_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_first_sort_order(p_firing_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(100000, 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_kind_sort_order(p_firing_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(1000, 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN (((SELECT NULLIF(second, '') FROM firings WHERE firing_id = p_firing_id)) IS NULL OR ((SELECT NULLIF(second, '') FROM firings WHERE firing_id = p_firing_id))::text = '') THEN (0)::text ELSE (calc_firings_second_sort_order(p_firing_id))::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_firings_is_chosen
-- Field: Firings.IsChosen
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_firings_is_chosen(p_firing_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_firings_fired_unit(p_firing_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(calc_firings_target_is_conclusion(p_firing_id), FALSE) AND COALESCE(COALESCE(calc_firings_order_key(p_firing_id), 0) = COALESCE(calc_firings_target_first_fired_order_key(p_firing_id), 0), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_firings_chosen_unit
-- Field: Firings.ChosenUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_firings_chosen_unit(p_firing_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN calc_firings_is_chosen(p_firing_id) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_firings_card_text
-- Field: Firings.CardText
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_firings_card_text(p_firing_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_firings_first_property(p_firing_id) AS val) SELECT (CASE WHEN calc_firings_is_chosen(p_firing_id) THEN (CONCAT('Worked out by the ', calc_firings_kind_wording(p_firing_id), ' from “', calc_firings_first_words(p_firing_id), '”', CASE WHEN COALESCE((SELECT NULLIF(kind, '') FROM firings WHERE firing_id = p_firing_id), '') = 'chain' THEN (CONCAT(' and “', calc_firings_second_words(p_firing_id), '”'))::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(kind, '') FROM firings WHERE firing_id = p_firing_id), '') = 'domain' THEN (CONCAT(' and “', (SELECT val FROM __erb_dedup_v1), ' has domain ', calc_firings_first_property_domain_class(p_firing_id), '”'))::text ELSE (CASE WHEN COALESCE((SELECT NULLIF(kind, '') FROM firings WHERE firing_id = p_firing_id), '') = 'range' THEN (CONCAT(' and “', (SELECT val FROM __erb_dedup_v1), ' has range ', calc_firings_first_property_range_class(p_firing_id), '”'))::text ELSE ('')::text END)::text END)::text END, '.'))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_firings_name
-- Field: Firings.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_firings_name(p_firing_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(firing_id, '') FROM firings WHERE firing_id = p_firing_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_disjoint_checks_rule_enabled
-- Field: DisjointChecks.RuleEnabled
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsEnabled from related Rules


CREATE OR REPLACE FUNCTION calc_disjoint_checks_rule_enabled(p_disjoint_check_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (SELECT is_enabled::boolean FROM rules WHERE rule_id = (SELECT rule FROM disjoint_checks WHERE disjoint_check_id = p_disjoint_check_id));
$$ LANGUAGE sql STABLE;

-- calc_disjoint_checks_first_holds
-- Field: DisjointChecks.FirstHolds
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: Holds from related Statements


CREATE OR REPLACE FUNCTION calc_disjoint_checks_first_holds(p_disjoint_check_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_statements_holds((SELECT first FROM disjoint_checks WHERE disjoint_check_id = p_disjoint_check_id));
$$ LANGUAGE sql STABLE;

-- calc_disjoint_checks_second_holds
-- Field: DisjointChecks.SecondHolds
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: Holds from related Statements


CREATE OR REPLACE FUNCTION calc_disjoint_checks_second_holds(p_disjoint_check_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_statements_holds((SELECT second FROM disjoint_checks WHERE disjoint_check_id = p_disjoint_check_id));
$$ LANGUAGE sql STABLE;

-- calc_disjoint_checks_subject_label
-- Field: DisjointChecks.SubjectLabel
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: SubjectLabel from related Statements


CREATE OR REPLACE FUNCTION calc_disjoint_checks_subject_label(p_disjoint_check_id TEXT)
RETURNS TEXT AS $$
  SELECT calc_statements_subject_label((SELECT first FROM disjoint_checks WHERE disjoint_check_id = p_disjoint_check_id));
$$ LANGUAGE sql STABLE;

-- calc_disjoint_checks_object_label
-- Field: DisjointChecks.ObjectLabel
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: ObjectLabel from related Statements


CREATE OR REPLACE FUNCTION calc_disjoint_checks_object_label(p_disjoint_check_id TEXT)
RETURNS TEXT AS $$
  SELECT calc_statements_object_label((SELECT first FROM disjoint_checks WHERE disjoint_check_id = p_disjoint_check_id));
$$ LANGUAGE sql STABLE;

-- calc_disjoint_checks_violation_unit
-- Field: DisjointChecks.ViolationUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_disjoint_checks_violation_unit(p_disjoint_check_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(calc_disjoint_checks_rule_enabled(p_disjoint_check_id), FALSE) AND COALESCE(calc_disjoint_checks_first_holds(p_disjoint_check_id), FALSE) AND COALESCE(calc_disjoint_checks_second_holds(p_disjoint_check_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_disjoint_checks_alarm_text
-- Field: DisjointChecks.AlarmText
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_disjoint_checks_alarm_text(p_disjoint_check_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((calc_disjoint_checks_violation_unit(p_disjoint_check_id))::NUMERIC, 0) = 1 THEN (CONCAT('Contradiction found. ', calc_disjoint_checks_subject_label(p_disjoint_check_id), ' is recorded as both parent and spouse of ', calc_disjoint_checks_object_label(p_disjoint_check_id), '. Check those facts and the selected disjoint rule.'))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_disjoint_checks_name
-- Field: DisjointChecks.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_disjoint_checks_name(p_disjoint_check_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(disjoint_check_id, '') FROM disjoint_checks WHERE disjoint_check_id = p_disjoint_check_id))::text;
$$ LANGUAGE sql STABLE;

